"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(arr, target):
    left = 0
    right = (len(arr) - 1)
    while (left <= right):
        mid = ((left + right) // 2)
        if (arr[mid] == target):
            return mid
        if (arr[left] <= arr[mid]):
            if ((arr[left] <= target) and (target < arr[mid])):
                right = (mid - 1)
            else:
                left = (mid + 1)
        else:
            if ((arr[mid] < target) and (target <= arr[right])):
                left = (mid + 1)
            else:
                right = (mid - 1)
    return (-1)


print(unnamed_function([4, 5, 6, 7, 0, 1, 2], 0))
print(unnamed_function([4, 5, 6, 7, 0, 1, 2], 3))